head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDODS70203";
scwin.formCd = "";
scwin.formNm = "";
scwin.formVer = "";
scwin.formText = "";
scwin.pageSize = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.pageSize = "" + dma_pageContext.get("pageSize") + "";
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods70203.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_ReportData.get("total")) + "건 [" + String(dma_ReportData.get("currentPage")) + "/" + String(dma_ReportData.get("endListPage")) + " 페이지]"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — jldods70203: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_2_onsubmit
 * @description form_2 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_2_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70203.form_2_onsubmit' }); }
};

/**
 * @method
 * @name ipt_searchWord_onkeyup
 * @description ipt_searchWord 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_searchWord_onkeyup = async function(e){
    try {
        await scwin.enterSearchForm()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70203.ipt_searchWord_onkeyup' }); }
};

/**
 * @method
 * @name input_9_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.input_9_onclick = async function(e){
    try {
        await scwin.goSearch()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70203.input_9_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        scwin.initPageIndex(); await scwin.goSearch();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70203.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_ReportDataList_oncellclick
 * @description grd_ReportDataList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_ReportDataList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_ReportDataList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_ReportDataList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.goAction(r["formCd"], r["formKorNm"], r["formVer"], r["sprtBzDtlNm"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_ReportDataList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_41_onclick
 * @description krxpage_pagenavigator_41 클릭 이벤트
 * @param {Number} index index
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.krxpage_pagenavigator_41_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_goSearchReq').set('pageIndex', pi);
        await scwin.goSearch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldods70203.krxpage_pagenavigator_41_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_goSearchReq').set('pageIndex', "1");
};

/**
 * @method
 * @name tx_goSearch
 * @description go Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_goSearch = async function () {
    try { return await $c.data.downFile("/discls/fssFile.do", "", ($c.util.getComponent("dma_goSearchReq") ? $c.util.getComponent("dma_goSearchReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name enterSearchForm
 * @description enter Search Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.enterSearchForm = async function () {
    if (event.keyCode === 13) {
        await scwin.goSearch();
    }
};

/**
 * @method
 * @name goSearch
 * @description go Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goSearch = async function () {
    blockLoading();
    $c.util.getComponent('dma_goSearchReq').set('method', "searchFssFile");
    await scwin.tx_goSearch();
};

/**
 * @method
 * @name selectData
 * @description select Data 처리
 * @param {String} fCd fCd
 * @param {String} fNm fNm
 * @param {*} fVer fVer
 * @param {*} fText fText
 * @returns {void}
 * @hidden N
 */
scwin.selectData = function (fCd, fNm, fVer, fText) {
    scwin.formCd = fCd;
    scwin.formNm = fNm;
    scwin.formVer = fVer;
    scwin.formText = fText;
};

/**
 * @method
 * @name select
 * @description select 처리
 * @returns {void}
 * @hidden N
 */
scwin.select = function () {
    (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).fn_setSelectedData === 'function' ? (scwin.openerScwin()).fn_setSelectedData(scwin.formCd, scwin.formNm, scwin.formVer, scwin.formText) : void 0), $c.win.closePopup([scwin.formCd, scwin.formNm, scwin.formVer, scwin.formText]));
    $c.win.closePopup();
};

/**
 * @method
 * @name goAction
 * @description go Action 처리
 * @param {String} formCd formCd
 * @param {String} formNm formNm
 * @param {*} formVer formVer
 * @param {*} formText formText
 * @returns {void}
 * @hidden N
 */
scwin.goAction = function (formCd, formNm, formVer, formText) {
    (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).fn_setSelectedData === 'function' ? (scwin.openerScwin()).fn_setSelectedData(formCd, formNm, formVer, formText) : void 0), $c.win.closePopup([formCd, formNm, formVer, formText]));
    $c.win.closePopup();
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
